#!/usr/bin/env python3
"""apply_batch19_step6.py - two things the pre-merge diff review caught.

Both were introduced by this review's own earlier steps, and neither had a
test, which is how they survived five batches. Reading the whole diff against
main before merging is what surfaced them.

  app/routes/share.py   Step 5's middleware defaults every response to
                        Cross-Origin-Resource-Policy: same-site. Correct for
                        the app, wrong for exactly one route: the share card
                        exists to be embedded somewhere else. same-site tells
                        a browser to refuse the image on any other origin,
                        which is the opposite of what a share card is for.
                        Telegram's own link preview fetches server-side and
                        would not have noticed, so this would have shown up
                        only as other people's blog posts rendering a broken
                        image. The card route now sets cross-origin for
                        itself.

  app/routes/web.py     _compute_asset_version hashed a hand-written list of
                        six filenames. Step 5 added static/countdown.css and
                        static/countdown.js without adding them to it, so any
                        later edit to either would have kept serving the copy
                        the browser already had - precisely the failure that
                        function's own docstring says it exists to prevent.
                        It now globs every shipped .css and .js, so the list
                        cannot fall behind again.

Two tests come with them, both checked against the versions they replace:

  test_share_card_can_be_embedded_cross_origin
  test_asset_version_covers_every_shipped_css_and_js

The second one touches each shipped file in turn and asserts the version
moves, so it fails the moment a new front-end file is added outside the hash.

Usage:
    python apply_batch19_step6.py --check   # resolve everything, write nothing
    python apply_batch19_step6.py           # apply

Guarded by the hash of each file's Step 5 version. UTF-8 and LF, through a
temp file and an atomic replace.
"""
from __future__ import annotations

import hashlib
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def read(path: Path) -> str:
    raw = path.read_text(encoding="utf-8")
    return raw.replace("\r\n", "\n").replace("\r", "\n")


def write_atomic(path: Path, content: str) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    with open(tmp, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(content)
    os.replace(tmp, path)


def sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


